# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">3. TEMA: ERDEMLER — "GARDAŞIM" ŞİİRİ VE ŞİİR BİLGİSİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Şiirde Anlam, Konu ve Ana Duygu</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Tema: Erdemler (Kardeşlik, Dostluk, Vefa)</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Konu: İnsan sevgisi, birlik, hoşgörü ve barış</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Ana Duygu: Kardeşçe yaşama ve paylaşma coşkusu</text>\n  <text x="180" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Bağlamdan kelime ve deyim anlamı tahmin etme</text>\n  <text x="180" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Söz Sanatları: Benzetme, Kişileştirme, Karşıtlık</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" fill="#334155">Şiirde ana fikir yerine "Ana Duygu" aranır!</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Şiirde Yapı ve Ahenk Unsurları</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Nazım Birimi: Dize (Mısra), Beyit (2), Dörtlük (4)</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Ölçü: Hece ölçüsü (Dizelerdeki ünlü sayısı eşitliği)</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Redif: Dize sonlarında aynı görevli ek/kelime tekrarı</text>\n  <text x="520" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Kafiye (Uyak): Farklı görevli ses benzerliği</text>\n  <text x="520" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Nakarat: Dörtlük sonunda tekrarlanan dize</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" fill="#166534">Vurgu ve tonlamaya dikkat ederek sesli okuma (T.8.3.2)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FİİLDE ÇATI UYGULAMALARI VE KARMA ÇATI ÇÖZÜMLEMESİ (T.8.4.19)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">1. Öznesine Göre (Özne - Yüklem İlişkisi)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Etken Çatı: Gerçek/Gizli özne var (-l, -n eki yok)</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11" fill="#713f12">  Örnek: "Şair kardeşlik şiirini okudu." (O okudu)</text>\n  <text x="180" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Edilgen Çatı: -l / -n eki var + Sözde Özne var</text>\n  <text x="180" y="170" text-anchor="middle" font-size="11" fill="#713f12">  Örnek: "Kardeşlik şiiri coşkuyla okundu." (Başkasınca)</text>\n  <text x="180" y="196" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Dönüşlü (Kendi kendine) &amp; İşteş (-ş ile karşılıklı)</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">LGS\'de temel ayrım: Etken (Gerçek) — Edilgen (Sözde)</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">2. Nesnesine Göre (Nesne - Yüklem İlişkisi)</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Geçişli Fiil: "Onu" zamirini alabilir (Nesne alır)</text>\n  <text x="520" y="120" text-anchor="middle" font-size="11" fill="#581c87">  Örnek: "Dost elini uzattı." ➔ (Onu uzattı ✓)</text>\n  <text x="520" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Geçişsiz Fiil: "Onu" zamirini alamaz (Nesne almaz)</text>\n  <text x="520" y="170" text-anchor="middle" font-size="11" fill="#581c87">  Örnek: "Gönülden gülümsedi." ➔ (Onu gülümsedi ✗)</text>\n  <text x="520" y="196" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">• ALTIN KURAL: Edilgen fiiller daima GEÇİŞSİZDİR!</text>\n  <text x="520" y="222" text-anchor="middle" font-size="11" fill="#475569">İsim cümlelerinde (yoktur, güzeldir, dosttur) çatı aranmaz!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CÜMLENİN ÖGELERİ VE CÜMLE TÜRLERİNE GİRİŞ (T.8.4.18)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">1. Yüklemin Türüne Göre Cümleler</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• Fiil (Eylem) Cümlesi: Yüklemi çekimli fiildir</text>\n  <text x="180" y="118" text-anchor="middle" font-size="11" fill="#881337">  "İnsanlar el ele vererek zorlukları aşar." (aş-ar)</text>\n  <text x="180" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• İsim (Ad) Cümlesi: Yüklemi ek fiil almış isim</text>\n  <text x="180" y="168" text-anchor="middle" font-size="11" fill="#881337">  veya fiilimsidir: "En büyük erdem dürüstlüktür."</text>\n  <text x="180" y="196" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">Dikkat: Yüklemi fiilimsi olan cümle İSİM cümlesidir!</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" fill="#881337">  "Amacımız dost kazanmaktır." (-mak: isim-fiil ➔ İsim)</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">2. Yüklemin Yerine (Öge Dizilişine) Göre</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• Kurallı (Düz) Cümle: Yüklem cümlenin SONUNDA</text>\n  <text x="520" y="118" text-anchor="middle" font-size="11" fill="#164e63">  "Tatlı dil yılanı deliğinden çıkarır."</text>\n  <text x="520" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• Devrik (Kuralsız) Cümle: Yüklem başta/ortada</text>\n  <text x="520" y="168" text-anchor="middle" font-size="11" fill="#164e63">  "Yeşerir sevgi tohumları dost gönüllerde." (Şiir dili)</text>\n  <text x="520" y="196" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• Eksiltili Cümle: Yüklemi söylenmemiş (...) cümle</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" fill="#164e63">  "Karşıda yemyeşil dağlar, şırıl şırıl akan dereler..."</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
